"use strict";

// C09: the same defect reached through an exact local object-literal
// member rather than an alias.
//
//     const handlers = { bail };
//     handlers.bail();
//
// This is NOT generic member resolution, and the module beside it
// (`valid.js`) carries the controls that prove so: a reassigned binding, an
// overwritten property, a safe-last duplicate key, a spread, and an object
// that escapes to a function which could rewrite the property. Every one of
// those really does complete, and every one must keep its later export.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("boom");
}

// `handlers` is a `const` object literal with no spread and no computed
// key, and the only thing this file ever does with it is read `.bail`.
const handlers = { bail };

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  handlers.bail();
}

module.exports = safeOp;
